    # is completed to a full digit by adding its vertical reflection and its
    # 180° rotation (both with a one‑cell shift towards the centre).  The original
    # pattern is also kept (with a possible one‑cell shift if needed).  All other
    # cells remain zero.
    if not grid:
        return grid
