    orig = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                orig[(r, c)] = grid[r][c]

    # Helper to add a transformed set of points to the output
    def add_transformed(out, trans):
        # trans is a list of (r,c,value)
        for r, c, v in trans:
            if 0 <= r <= max_r and 0 <= c <= max_c:
                out[(r, c)] = v

    # Start with original cells (shifted up by one row to centre the digit)
    output = {}
    for (r, c), v in orig.items():
        nr = r - 1            # shift up by one
        if 0 <= nr <= max_r:
            output[(nr, c)] = v

    # Vertical reflection (mirror across the horizontal centre line) with the same shift
    trans_v = []
    for (r, c), v in orig.items():
        nr = max_r - r - 1    # reflect and shift up one
        trans_v.append((nr, c, v))
    add_transformed(output, trans_v)

    # 180° rotation (mirror across both axes) – also with the same shift
    trans_b = []
    for (r, c), v in orig.items():
        nr = max_r - r - 1
        nc = max_c - c
        trans_b.append((nr, nc, v))
    add_transformed(output, trans_b)

    # Build the resulting grid
    result = [[0 for _ in range(cols)] for _ in range(rows)]
    for (r, c), v in output.items():
        result[r][c] = v
    return result
